SELECT jsonb_build_object('functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','zoi') AND p.proname ~* '(inquir|conversation|message|inbox)'), 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('diaspora_conversations','diaspora_messages')),'policies',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'policy',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check)) FROM pg_policies WHERE tablename IN('diaspora_conversations','diaspora_messages'))) AS inquiry_contract_review;
